/* @component: .nature-video */
(function() {
  const init = () => {
    const wrappers = document.querySelectorAll('.nature-video');
    wrappers.forEach(wrap => {
      const v = wrap.querySelector('video');
      if (v && !v.classList.contains('plyr--setup') && !v.closest('.plyr')) {
         v.classList.add('plyr--setup');
         new Plyr(v, {
          controls: ['play-large', 'play', 'progress', 'current-time', 'mute', 'volume', 'fullscreen'],
          ratio: '16:9'
        });
      }
    });
  };

  if (typeof Plyr === 'undefined') {
    if (!document.querySelector('#plyr-lib')) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = 'https://cdn.plyr.io/3.7.8/plyr.css';
      document.head.appendChild(link); 

      const script = document.createElement('script');
      script.id = 'plyr-lib';
      script.src = 'https://cdn.plyr.io/3.7.8/plyr.js';
      script.onload = () => setTimeout(init, 100); 
      document.head.appendChild(script);
    }
  } else {
    init();
  }
})();
